  1	import java.util.ArrayList;
  2	import java.util.Comparator;
  3	import java.util.Objects;
  4	import java.util.PriorityQueue;
  5	
  6	class HuffmanCoding {
  7	
  8	    private static final int INTERNAL_NODE_SYMBOL_INDEX = -1;
  9	    private static final String SINGLE_SYMBOL_CODE = "0";
 10	
 11	    private static final Comparator<Node> NODE_ORDER = Comparator
 12	            .comparingLong((Node node) -> node.frequency)
 13	            .thenComparingInt(node -> node.firstSymbolIndex);
 14	
 15	    private HuffmanCoding() {
 16	    }
 17	
 18	    private static final class Node {
 19	        private final long frequency;
 20	        private final int firstSymbolIndex;
 21	        private final int symbolIndex;
 22	        private final Node left;
 23	        private final Node right;
 24	
 25	        private Node(int frequency, int symbolIndex) {
 26	            this.frequency = frequency;
 27	            this.firstSymbolIndex = symbolIndex;
 28	            this.symbolIndex = symbolIndex;
 29	            this.left = null;
 30	            this.right = null;
 31	        }
 32	
 33	        private Node(Node left, Node right) {
 34	            this.frequency = left.frequency + right.frequency;
 35	            this.firstSymbolIndex = Math.min(left.firstSymbolIndex, right.firstSymbolIndex);
 36	            this.symbolIndex = INTERNAL_NODE_SYMBOL_INDEX;
 37	            this.left = left;
 38	            this.right = right;
 39	        }
 40	
 41	        private boolean isLeaf() {
 42	            return left == null && right == null;
 43	        }
 44	    }
 45	
 46	    private interface LeafCodeConsumer {
 47	        void accept(Node leaf, String code);
 48	    }
 49	
 50	    private static final class HuffmanTree {
 51	        private final Node root;
 52	        private final int symbolCount;
 53	
 54	        private HuffmanTree(Node root, int symbolCount) {
 55	            this.root = root;
 56	            this.symbolCount = symbolCount;
 57	        }
 58	
 59	        private static HuffmanTree build(String symbols, int[] frequencies) {
 60	            validateInput(symbols, frequencies);
 61	            Node root = symbols.isEmpty() ? null : buildTree(frequencies);
 62	            return new HuffmanTree(root, symbols.length());
 63	        }
 64	
 65	        private ArrayList<String> codesInTraversalOrder() {
 66	            ArrayList<String> codes = new ArrayList<>(symbolCount);
 67	            collectLeafCodes(root, new StringBuilder(), (leaf, code) -> codes.add(code));
 68	            return codes;
 69	        }
 70	
 71	        private ArrayList<String> codesBySymbolOrder() {
 72	            ArrayList<String> codes = createEmptyCodeList(symbolCount);
 73	            collectLeafCodes(root, new StringBuilder(), (leaf, code) -> codes.set(leaf.symbolIndex, code));
 74	            return codes;
 75	        }
 76	    }
 77	
 78	    static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
 79	        return HuffmanTree.build(symbols, frequencies).codesInTraversalOrder();
 80	    }
 81	
 82	    static ArrayList<String> huffmanCodesBySymbol(String symbols, int[] frequencies) {
 83	        return HuffmanTree.build(symbols, frequencies).codesBySymbolOrder();
 84	    }
 85	
 86	    private static void validateInput(String symbols, int[] frequencies) {
 87	        Objects.requireNonNull(symbols, "Input string must not be null");
 88	        Objects.requireNonNull(frequencies, "Frequency array must not be null");
 89	
 90	        if (symbols.length() != frequencies.length) {
 91	            throw new IllegalArgumentException("Input string and frequency array must have the same length");
 92	        }
 93	    }
 94	
 95	    private static Node buildTree(int[] frequencies) {
 96	        PriorityQueue<Node> nodes = createLeafQueue(frequencies);
 97	
 98	        while (nodes.size() > 1) {
 99	            nodes.add(mergeLowestFrequencyNodes(nodes));
100	        }
101	
102	        return nodes.poll();
103	    }
104	
105	    private static PriorityQueue<Node> createLeafQueue(int[] frequencies) {
106	        PriorityQueue<Node> nodes = new PriorityQueue<>(NODE_ORDER);
107	
108	        for (int i = 0; i < frequencies.length; i++) {
109	            nodes.add(new Node(frequencies[i], i));
110	        }
111	
112	        return nodes;
113	    }
114	
115	    private static Node mergeLowestFrequencyNodes(PriorityQueue<Node> nodes) {
116	        Node left = nodes.poll();
117	        Node right = nodes.poll();
118	        return new Node(left, right);
119	    }
120	
121	    private static ArrayList<String> createEmptyCodeList(int size) {
122	        ArrayList<String> codes = new ArrayList<>(size);
123	
124	        for (int i = 0; i < size; i++) {
125	            codes.add("");
126	        }
127	
128	        return codes;
129	    }
130	
131	    private static void collectLeafCodes(Node root, StringBuilder prefix, LeafCodeConsumer consumer) {
132	        if (root == null) {
133	            return;
134	        }
135	
136	        if (root.isLeaf()) {
137	            consumer.accept(root, codeFor(prefix));
138	            return;
139	        }
140	
141	        appendBranchCode(root.left, '0', prefix, consumer);
142	        appendBranchCode(root.right, '1', prefix, consumer);
143	    }
144	
145	    private static void appendBranchCode(Node node, char bit, StringBuilder prefix, LeafCodeConsumer consumer) {
146	        prefix.append(bit);
147	        collectLeafCodes(node, prefix, consumer);
148	        prefix.setLength(prefix.length() - 1);
149	    }
150	
151	    private static String codeFor(StringBuilder prefix) {
152	        return prefix.length() == 0 ? SINGLE_SYMBOL_CODE : prefix.toString();
153	    }
154	
155	    public static void main(String[] args) {
156	        String s = "abcdef";
157	        int[] freq = {5, 9, 12, 13, 16, 45};
158	        ArrayList<String> codes = huffmanCodes(s, freq);
159	
160	        for (String code : codes) {
161	            System.out.print(code + " ");
162	        }
163	    }
164	}
